function o(n){return!n||typeof n!="object"||Array.isArray(n)?null:n}function i(n){return typeof n=="number"&&Number.isFinite(n)?Math.trunc(n):0}function s(n){return typeof n=="string"?n:""}function e(n){return typeof n=="boolean"?n:!1}function f(n){return typeof n=="string"?n:null}function u(n,t){const r=t.toString();return r?`${n}?${r}`:n}export{o as a,i as b,s as c,f as d,e,u as w};
